package dev.crowncinder.world;
import dev.crowncinder.item.ModItems;import net.minecraft.item.ItemStack;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.text.Text;import net.minecraft.util.math.BlockPos;import net.minecraft.world.Heightmap;
public final class NationWorld{public static final String[] NATIONS={"aurelia","eldoria","kharum","sylvan","varkhan"};private NationWorld(){}public static BlockPos center(ServerWorld w,String n){BlockPos s=w.getSpawnPos();int dx=0,dz=0;switch(n){case "aurelia"->{dx=180;dz=0;}case "eldoria"->{dx=55;dz=-170;}case "kharum"->{dx=-145;dz=-105;}case "sylvan"->{dx=-145;dz=105;}case "varkhan"->{dx=55;dz=170;}}int x=s.getX()+dx,z=s.getZ()+dz;int y=w.getTopY(Heightmap.Type.MOTION_BLOCKING_NO_LEAVES,x,z)-1;return new BlockPos(x,y,z);}public static void buildAll(ServerPlayerEntity p){ServerWorld w=p.getServerWorld();for(String n:NATIONS)NationSettlement.build(w,center(w,n),n);giveMap(p);p.sendMessage(Text.literal("§6[왕국 개척] §f월드 스폰 주변에 5개 국가 초기 거점을 생성했습니다."),false);}public static void giveMap(ServerPlayerEntity p){ItemStack s=new ItemStack(ModItems.KINGDOM_MAP);if(!p.getInventory().insertStack(s))p.dropItem(s,false);}public static void showMap(ServerPlayerEntity p){ServerWorld w=p.getServerWorld();BlockPos here=p.getBlockPos();p.sendMessage(Text.literal("§e==== Crown & Cinder 왕국 지도 ===="),false);for(String n:NATIONS){BlockPos c=center(w,n);double d=Math.sqrt(here.getSquaredDistance(c));p.sendMessage(Text.literal("§6"+RpgOutpost.nationName(n)+" §f| "+direction(c.getX()-here.getX(),c.getZ()-here.getZ())+" 약 "+Math.round(d)+"블록 | X "+c.getX()+" Z "+c.getZ()),false);}}private static String direction(int dx,int dz){String ns=dz<-20?"북":dz>20?"남":"";String ew=dx>20?"동":dx<-20?"서":"";String r=ns+ew;return r.isEmpty()?"현재 위치 근처":r;}}
